// Data model for the curriculum tracker. Curriculum content is generated by
// scripts/parse-curriculum.ts into content/curriculum.json; progress lives in
// localStorage (see src/store.ts).

export type PhaseId = "P" | 0 | 1 | 2 | 3 | "C"; // "P" is the CS primer, "C" the capstone
export type WeekId = string; // "P1".."P5", then "1".."44"; ordering: primer first, then numeric
export type Depth = "built" | "derived" | "lecture";

export type Phase = {
  id: PhaseId;
  name: string;
  weeks: [WeekId, WeekId];
  hours: number;
  exitCondition: string;
  checkpoints: Checkpoint[];
};

export type Week = {
  id: WeekId;
  order: number;
  phase: PhaseId;
  lecture: string;
  reading: string;
  exercise: string;
  hours: number;
  gate?: string;
  depth: Depth;
  /** Resource ids cited by this week's row (resolved by the parser). */
  resources: string[];
  /** Paper ids cited by this week's row. */
  papers: string[];
  /** Hash of the source row text; used by resync to detect changed rows. */
  hash: string;
};

export type Checkpoint = { id: string; phase: PhaseId; text: string };
export type Derivation = { id: string; title: string; phase: PhaseId; weekDue: WeekId };
export type Competency = { id: string; name: string; phaseSet: PhaseId; target: 1 | 2 };
export type Paper = {
  id: string;
  title: string;
  year?: number;
  weeks: WeekId[];
  url?: string;
  urlStatus: "source" | "unverified" | "none";
};
export type Resource = {
  id: string;
  name: string;
  url?: string;
  kind: "course" | "book" | "repo" | "lectures" | "tool" | "paper";
  /** Which source file the URL came from. */
  source?: "curriculum" | "lesson-plan" | "llm-course";
};
export type ReviewEntry = { date: string; change: string };

export type Curriculum = {
  generatedFrom: { curriculum: string; lessonPlan: string };
  title: string;
  canonicalUrl: string;
  totals: { activeWeeks: number; bufferWeeks: number; hoursPerWeek: number; plannedHours: number };
  depthMap: { depth: Depth | "left-out"; meaning: string; areas: string }[];
  judgmentQuestions: string[];
  levelScale: Record<string, string>;
  competencyRule: string;
  phases: Phase[];
  weeks: Week[];
  checkpoints: Checkpoint[];
  derivations: Derivation[];
  competencies: Competency[];
  papers: Paper[];
  resources: Resource[];
  reviews: ReviewEntry[];
  milestones: { name: string; weeks: string; notes: string }[];
};

export type WeekStatus = "not_started" | "in_progress" | "done" | "skipped";
export type Level = "U" | 1 | 2 | 3 | 4;
export type PaperDepth = "unread" | "skim" | "methods" | "deep";

export type WeekProgress = {
  status: WeekStatus;
  hours: number;
  started?: string;
  done?: string;
  notes: string;
  exerciseDone: boolean;
};

export type LogEntry = {
  week: WeekId;
  dates: string;
  hours: number;
  done: string;
  unaided: string;
  stuck: string;
  created: string;
};

export type Progress = {
  version: 1;
  startDate?: string;
  targetHoursPerWeek: number; // default 6
  weeks: Record<WeekId, WeekProgress>;
  derivations: Record<
    string,
    { done: boolean; date?: string; closedBook: boolean; retestDue?: string; retestResult?: string }
  >;
  competencies: Record<string, { level: Level; evidence: string; date?: string; retestDue?: string }>;
  checkpoints: Record<string, { done: boolean; date?: string; link?: string }>;
  papers: Record<
    string,
    { depth: PaperDepth; claim: string; evidence: string; weakest: string; judgmentFails: string[]; date?: string }
  >;
  log: LogEntry[];
  reviews: Array<{ date: string; change: string }>;
  specialization?: string;
  /** ISO timestamp of the last "Report to Claude" copy. */
  lastReportAt?: string;
  /** Change journal used by the report: what changed since lastReportAt. */
  changes: Array<{ at: string; kind: "week" | "competency" | "derivation" | "paper"; id: string; detail: string }>;
};
